/** Mixed STEP 2/3 topics and STEP 3 additions. */
import { tex as r, technique as t, linkedProblem as q } from './admissions-authoring.js';

export const stepFurtherPureContent = {
  'pure/complex': {
    bullets: [
      t('Cartesian complex arithmetic and conjugates', '复数运算与共轭', '把实部虚部分开运算，共轭可把复数分母变成实数，也限制实系数多项式的非实根。', '实系数多项式的非实根成共轭对；复系数情况不能照搬。', r`z\bar z=|z|^2,\qquad\frac1z=\frac{\bar z}{|z|^2}\quad(z\ne0)`, '先用虚数单位平方为负一化简，再合并实虚部；除法乘共轭时同时处理分子分母。', r`例如 \(\frac1{1+i}=\frac{1-i}2\)，而 \((1+i)^2=2i\)。`, '复数之间没有与实数相同的通常大小顺序；不能写某复数大于另一个复数。'),
      t('Modulus-argument multiplication', '模辐角形式的乘除', '复数乘法同时相乘长度、相加转角，几何上对应伸缩与旋转。', '辐角相差整周表示同一方向；主辐角需遵循指定区间。', r`r_1(\cos\theta_1+i\sin\theta_1)r_2(\cos\theta_2+i\sin\theta_2)=r_1r_2\bigl(\cos(\theta_1+\theta_2)+i\sin(\theta_1+\theta_2)\bigr)`, '由实虚部判断象限，再算模与辐角；除法时减角且除数模非零。', r`例如乘以 i 将非零复数逆时针旋转 \(\frac\pi2\)，模保持不变。`, '仅用反正切不能决定象限；零复数的辐角没有定义。'),
      t('Argand loci and excluded vertices', '复平面轨迹与禁点', '模表示距离，辐角表示方向，复数条件可以转化为圆、垂直平分线或射线。', '辐角约束不能包含使内部复数为零的顶点。', r`|z-a|=|z-b|\quad\text{is the perpendicular bisector when }a\ne b`, '先用几何理解，再设实虚部得到坐标方程；联合条件时求轨迹交集。', r`例如 \(|z-1|=|z+1|\) 表示虚轴；\(|z-i|=2\) 表示以 i 为圆心的圆。`, '辐角固定通常给射线而非整条直线；商的辐角还要排除分母为零。'),
      t('De Moivre and multiple angles', '棣莫弗与倍角', '把整数次幂中的模和角分开，可推导倍角公式与三角和，属于 STEP 3 新增工具。', '整数次幂把辐角乘整数；开根则需要列出所有不同分支。', r`(\cos\theta+i\sin\theta)^n=\cos(n\theta)+i\sin(n\theta)\quad(n\in\mathbb Z)`, '展开代数式并比较实部虚部；负整数幂先保证复数非零。', r`例如比较三次幂虚部得到 \(\sin3\theta=3\sin\theta-4\sin^3\theta\)。`, '非整数指数涉及分支，不能不加条件使用相同公式。', 'STEP 3'),
      t('Complex roots and regular polygons', '复数开根与正多边形', '非零复数的 n 次根均匀分布在同一个圆上，相邻辐角相差一个整周的 n 分之一。', 'STEP 3 开根需给全体 n 个不同根，不能只写主值。', r`z^n=Re^{i\theta}\Rightarrow z_k=R^{\frac1n}e^{\frac{i(\theta+2k\pi)}n},\quad k=0,\ldots,n-1`, '列有限个代表角，再利用单位根几何级数或正多边形对称简化和积。', r`例如三次单位根为 \(1,\omega,\omega^2\)，且 \(1+\omega+\omega^2=0\)。`, '零的 n 次根只有一个不同值；几何级数求和时先排除公比等于一。', 'STEP 3'),
    ],
    exercises: [
      q('complex-locus', 'Intersecting two loci', r`A complex number \(z\) satisfies \(|z-1|=|z+1|\) and \(|z-2i|=2\). (i) Describe each locus. (ii) Find all possible values of \(z\).`, '第一个条件是两点的垂直平分线；再代入第二个圆。', [r`The first locus is the imaginary axis, the perpendicular bisector of the segment from \(-1\) to \(1\). The second is the circle with centre \(2i\) and radius 2.`, r`Write \(z=iy\), with real \(y\). Then \(|y-2|=2\), so \(y=0\) or 4. The two values are \(z=0,4i\).`]),
      q('cube-roots', 'Three roots of a negative real number', r`(i) Find all solutions of \(z^3=-8\). (ii) Show that their sum is zero. (iii) Describe their positions geometrically.`, '先把负八的辐角写成圆周率加整周，再分别除以三。', [r`Write \(-8=8e^{i(\pi+2k\pi)}\). The three distinct roots are \(2e^{i\frac\pi3}=1+i\sqrt3\), \(2e^{i\pi}=-2\), and \(2e^{i\frac{5\pi}3}=1-i\sqrt3\).`, r`Their sum is zero. Each has modulus 2 and their arguments are equally spaced by \(\frac{2\pi}3\), so they form an equilateral triangle centred at the origin.`], false, 'STEP 3'),
    ],
  },
  'pure/matrices': {
    bullets: [
      t('Matrix composition order', '矩阵复合的顺序', '矩阵作用于列向量时，先做的变换写在右边；乘法通常不可交换。', '先 A 后 B 的合成矩阵为 BA。', r`v\mapsto Av\mapsto BAv`, '先核对矩阵维度，再以简单基向量追踪顺序；检查乘积是否反映预期几何效果。', '例如先沿横向伸缩再旋转，与先旋转再横向伸缩一般会得到不同图形。', '矩阵元素不能按对应位置直接相乘；乘法可定义也不保证交换顺序后有同样结果。'),
      t('Determinants, inverses and singularity', '行列式、逆矩阵与奇异性', '二维行列式给带方向的面积倍率；非零时才能用逆矩阵唯一还原输入。', '面积倍率取行列式绝对值，行列式符号记录方向是否翻转。', r`\begin{pmatrix}a&b\\c&d\end{pmatrix}^{-1}=\frac1{ad-bc}\begin{pmatrix}d&-b\\-c&a\end{pmatrix}\quad(ad-bc\ne0)`, '先算行列式，再决定是否求逆；用与原矩阵相乘得到单位矩阵核验。', r`例如 \(\operatorname{diag}(2,-3)\) 把面积放大六倍，并翻转方向。`, '行列式为零意味着无法唯一还原，不代表所有相应线性系统都没有解。'),
      t('Fixed points and invariant lines', '不动点与不变直线', '不动点逐点保持，不变直线则允许点沿线移动，二者是不同的集合要求。', '不动点解 Av=v；过原点的不变方向只需 Av 与 v 平行。', r`Av=v\quad\text{versus}\quad Av=\lambda v\ (v\ne0)`, '先按题意区别点不动和集合不变；一般直线还要检查截距是否变回原直线。', r`例如矩阵 \(\operatorname{diag}(2,1)\) 的纵轴逐点不动，横轴整体不变却非逐点不动。`, '检查一条直线上单个点不足以证明整条线不变；零向量不能单独确定方向。'),
      t('Three-dimensional elementary transformations', '三维基本矩阵变换', 'STEP 2 已包括坐标平面反射和绕坐标轴的基本三维旋转，不能把所有三阶矩阵都视为 STEP 3。', '旋转轴方向保持不变，其余两坐标作平面旋转。', r`R_z(\theta)=\begin{pmatrix}\cos\theta&-\sin\theta&0\\\sin\theta&\cos\theta&0\\0&0&1\end{pmatrix}`, '先确定轴与旋转正向，再追踪三个坐标基向量；用长度保持检查矩阵。', r`例如关于平面 \(x=0\) 的反射为 \((x,y,z)\mapsto(-x,y,z)\)。`, '基本三维变换与一般三阶逆矩阵、行列式的要求属于不同范围，不应混为一谈。'),
      t('Three-by-three systems and geometry', '三阶系统与几何解读', 'STEP 3 用三阶行列式与逆矩阵处理三个平面的交集，并解释无解或多解。', '三阶行列式非零时解唯一；为零时需继续检查相容性。', r`Ax=b,\quad\det A\ne0\Rightarrow x=A^{-1}b`, '按一致顺序排列未知数，计算行列式或消元；特殊参数下回到原方程检查。', '例如三个独立平面交于一点，平行但不重合的约束可能无公共解，重复约束可能留下直线。', '不能以“行列式为零”直接断言无解，也不能把一般三维求逆默认为 STEP 2。', 'STEP 3'),
    ],
    exercises: [
      q('matrix-fixed', 'A transformation and its fixed points', r`Let \(A=\begin{pmatrix}2&1\\0&1\end{pmatrix}\). (i) Find \(A^{-1}\). (ii) Find every fixed point. (iii) Find the area of the image of the unit square.`, '固定点要求变换后的两个坐标逐一等于原坐标。', [r`The determinant is 2, so \(A^{-1}=\begin{pmatrix}\frac12&-\frac12\\0&1\end{pmatrix}\).`, r`The equation \((2x+y,y)=(x,y)\) gives \(x+y=0\). Every point on that line is fixed.`, r`The unit square has area 1, and area scales by \(|\det A|=2\), so its image has area 2.`]),
      q('matrix-three-system', 'A three-dimensional linear system', r`Let \(A=\begin{pmatrix}1&1&0\\0&1&1\\1&0&1\end{pmatrix}\). (i) Find its determinant. (ii) Solve \(A(x,y,z)^{\mathsf T}=(3,5,4)^{\mathsf T}\). (iii) Interpret uniqueness geometrically.`, '先求行列式，再把三个和式相加与相减。', [r`Expansion along the first row gives \(\det A=1-(-1)=2\ne0\).`, r`The equations are \(x+y=3\), \(y+z=5\), \(x+z=4\). Adding them gives \(x+y+z=6\), so \(x=1,y=2,z=3\).`, 'The three planes meet at this single point. The nonzero determinant guarantees a unique solution for every right-hand side.'], false, 'STEP 3'),
    ],
  },
  'pure/vectors': {
    bullets: [
      t('Vector lines and intersections', '向量直线与交点', '直线由一个已知点与非零方向向量确定，两个直线参数应独立设置再联立。', '先分别设参数，求解后必须核对全部坐标。', r`\mathbf r=\mathbf a+t\mathbf d\quad(\mathbf d\ne\mathbf0)`, '从两点相减得到方向；相交要求存在一对参数使各坐标同时相等。', r`例如过 \((1,0,2)\)、方向 \((2,1,-1)\) 的直线可写为 \((1+2t,t,2-t)\)。`, '空间两直线不平行也可能异面；仅匹配两个坐标不足以证明相交。'),
      t('Scalar products and angles', '点积与夹角', '点积把长度和夹角联系起来，也可以统一处理垂直与投影，不必依赖斜率。', '非零向量点积为零等价于互相垂直。', r`\mathbf a\cdot\mathbf b=|\mathbf a||\mathbf b|\cos\theta`, '在坐标下逐分量相乘再相加；求角前先求模，几何直线锐角需按题意选取。', r`例如 \((1,2,-1)\cdot(1,0,1)=0\)，这两个非零方向互相垂直。`, '零向量没有定义夹角；点积结果是标量，不是新的方向向量。'),
      t('Plane equations and line-plane angles', '平面方程与线面角', '平面的法向量与所有面内方向垂直；线面角与方向向量和法向量的夹角互余。', '线面角公式使用正弦，不能直接把线与法向量的夹角当成线面角。', r`\mathbf n\cdot(\mathbf r-\mathbf a)=0,\qquad\sin\phi=\frac{|\mathbf d\cdot\mathbf n|}{|\mathbf d||\mathbf n|}`, '先找一个面内点和法向量，再代入直线参数；检查平行、包含或唯一相交。', r`平面 \(x+2y+2z=9\) 的一个法向量为 \((1,2,2)\)，而非平面内方向。`, '平行直线可能完全在平面内，也可能与平面没有交点，需要检查常数项。', 'STEP 3'),
      t('Vector products and oriented areas', '叉积与面积', '叉积垂直于两向量张成的平面，模等于相应平行四边形面积。', '交换叉积顺序会反向；三角形面积是叉积模的一半。', r`A_{\triangle}=\frac12|\mathbf a\times\mathbf b|`, '选从同一顶点出发的两条边，求叉积后取模；方向按右手规则解释。', r`例如单位横向与单位纵向向量的叉积为单位竖向向量，所得三角形面积为二分之一。`, '叉积不是逐分量相乘；共线时叉积为零，因此不能把它当非零法向量。', 'STEP 3'),
      t('Perpendicular distances in space', '空间垂直距离', '距离取最短的垂直分量；点到平面用法向投影，异面直线可用共同垂直方向。', '先确定几何关系，再选点线、点面或异面线的对应公式。', r`d(P,\Pi)=\frac{|\mathbf n\cdot\mathbf p-c|}{|\mathbf n|}\quad(\Pi:\mathbf n\cdot\mathbf r=c)`, '点到线可先设垂足并要求连线垂直方向；异面线用两方向叉积作法向，再投影两基点差。', r`原点到 \(x+2y+2z=9\) 的距离为 \(\frac9{\sqrt{1+4+4}}=3\)。`, '平行线的方向叉积为零，不能用除以该叉积模的异面线公式；距离必须非负。', 'STEP 3'),
    ],
    exercises: [
      q('vector-line-point', 'A line and a perpendicular direction', r`A line has equation \(\mathbf r=(1,0,1)+t(1,2,-1)\). (i) Find its point with y-coordinate 2. (ii) Show its direction is perpendicular to \((1,0,1)\). (iii) Give a distinct parallel line through the origin.`, '第一问先由纵坐标确定参数；第二问使用点积。', [r`The y-coordinate is \(2t\), so \(t=1\) and the point is \((2,2,0)\).`, r`The dot product is \((1,2,-1)\cdot(1,0,1)=1-1=0\), proving perpendicularity.`, r`A parallel line through the origin is \(\mathbf r=s(1,2,-1)\). It is distinct because \((1,0,1)\) is not a scalar multiple of \((1,2,-1)\).`]),
      q('plane-foot', 'A plane, a foot and an intersection', r`Let \(\Pi\) be the plane \(x+2y+2z=9\). (i) Find the perpendicular distance from the origin to \(\Pi\). (ii) Find the perpendicular foot. (iii) Find where \(\mathbf r=t(1,1,0)\) meets \(\Pi\).`, '垂足沿法向量方向；第三问将参数直线代入平面。', [r`A normal is \(\mathbf n=(1,2,2)\), of length 3. The distance is \(\frac93=3\).`, r`The foot is \(s(1,2,2)\). Substitution gives \(9s=9\), so it is \((1,2,2)\).`, r`On the line, the plane equation becomes \(t+2t=9\), so \(t=3\) and the intersection is \((3,3,0)\).`], false, 'STEP 3'),
    ],
  },
  'pure/series': {
    bullets: [
      t('Maclaurin coefficients and validity', '麦克劳林系数与有效区间', '在零附近用各阶导数确定幂级数系数，再单独注明级数等于函数的范围。', '系数由导数除以阶乘得到；存在各阶导数本身不保证级数处处等于函数。', r`f(x)=\sum_{n=0}^{\infty}\frac{f^{(n)}(0)}{n!}x^n\quad\text{where the expansion is valid}`, '掌握指数、正弦、余弦、对数和二项式的标准展开；复合变量后重新换算收敛区间。', r`例如 \(\ln(1+x)=x-\frac{x^2}2+\frac{x^3}3-\cdots\)，至少在 \(|x|<1\) 内有效。`, '端点需分别检验，不能由开区间条件自动纳入；展开中心不是任意位置。', 'STEP 3'),
      t('Leading terms in limits', '极限中的主导项', '相减会抵消低阶项，只有保留到首个不为零的阶数，才知道分子分母的相对大小。', '先找消去到哪一阶，再截断到足以决定极限的阶数。', r`e^x-1-x=\frac{x^2}2+O(x^3)\quad(x\to0)`, '分别展开到足够高阶，合并后比较最小幂次；必要时注明余项阶数。', r`例如 \(\frac{e^x-1-x}{x^2}\to\frac12\)，只保留常数和一次项无法求值。`, '不能在低阶项全部抵消后把余项当作零；近似符号也不能直接替换成恒等。', 'STEP 3'),
      t('Cartesian and parametric arc length', '直角坐标与参数弧长', '弧长来自微小直角三角形的斜边之和，参数曲线使用两个方向速度的合成模。', '确认参数是否重复描绘曲线，再设置积分区间。', r`L=\int_{t_0}^{t_1}\sqrt{\left(\frac{dx}{dt}\right)^2+\left(\frac{dy}{dt}\right)^2}\,dt`, '求参数导数，先在根号内因式分解；根号开出平方项时保留绝对值。', r`例如 \(x=3t,y=4t\)，从零到一的弧长为 \(\int_0^1 5\,dt=5\)。`, '横坐标变化量不是弧长；来回描线会在参数积分中重复计入路程。', 'STEP 3'),
      t('Volumes of revolution and function means', '旋转体积与函数平均值', '旋转体用薄圆盘或圆环累积体积，函数平均值则把总积分分配到区间长度。', '旋转半径需要平方，函数平均值要除以区间长度。', r`V=\pi\int_a^b y^2\,dx,\qquad f_{\mathrm{avg}}=\frac1{b-a}\int_a^b f(x)\,dx\quad(a<b)`, '先确定旋转轴与内外半径，再写面积差；平均值明确自变量和区间。', r`例如 \(y=\sqrt x\) 在零到一绕横轴旋转体积为 \(\frac\pi2\)，函数平均值为 \(\frac23\)。`, '绕不同轴旋转时半径表达式不同；函数平均值不是两端函数值的简单平均。', 'STEP 3'),
    ],
    exercises: [
      q('series-log-limit', 'A logarithmic cancellation', r`(i) Write the first three nonzero terms of the Maclaurin series for \(\ln(1+x)\), stating an open interval where it is valid. (ii) Evaluate \(\lim_{x\to0}\frac{\ln(1+x)-x+\frac{x^2}2}{x^3}\).`, '分子的一次和二次项都抵消，需要保留三次项。', [r`For \(|x|<1\), \(\ln(1+x)=x-\frac{x^2}2+\frac{x^3}3+O(x^4)\).`, r`The numerator is \(\frac{x^3}3+O(x^4)\), so division by \(x^3\) gives the limit \(\frac13\).`], false, 'STEP 3'),
      q('parametric-length', 'An arc-length substitution', r`A curve has \(x=t^2\), \(y=\frac23t^3\), for \(0\le t\le1\). (i) Find its speed in the parameter. (ii) Calculate its length.`, '导数平方和可提出参数的平方，再用一加参数平方换元。', [r`The derivatives are \(2t\) and \(2t^2\), so the speed is \(\sqrt{4t^2+4t^4}=2t\sqrt{1+t^2}\), since \(t\ge0\).`, r`Hence \(L=\int_0^1 2t\sqrt{1+t^2}\,dt=\int_1^2 u^{\frac12}\,du=\frac23(2\sqrt2-1)\).`], false, 'STEP 3'),
    ],
  },
  'pure/polar-hyperbolic': {
    bullets: [
      t('Polar coordinates and traced intervals', '极坐标与描线区间', '极坐标用距离与方向表示位置，草图先检查半径非负、对称和角度实际覆盖区域。', '本考纲取半径非负；相同点可能对应不同角度，不能重复计面积。', r`x=r\cos\theta,\quad y=r\sin\theta,\quad r^2=x^2+y^2`, '先列关键角和半径，再转换简单关系验证图形；说明起止角与是否经过原点。', r`例如 \(r=2\cos\theta\) 在 \(-\frac\pi2\le\theta\le\frac\pi2\) 描绘圆 \((x-1)^2+y^2=1\)。`, '负半径属于别的约定，本框架不采用；消去角度后仍要检查原角度范围。', 'STEP 3'),
      t('Polar area and repeated regions', '极坐标面积与重复区域', '很薄的扇形面积约为半径平方乘半角增量，累积后得到极坐标面积公式。', '先确认积分角段恰好描一遍目标区域。', r`A=\frac12\int_\alpha^\beta r(\theta)^2\,d\theta`, '画草图并找交点角；两曲线间面积使用外半径平方减内半径平方。', r`半径恒为 a、角度从零到圆周率的区域面积为 \(\frac12\pi a^2\)。`, '半径差的平方不等于平方之差；多个花瓣重复描绘时要调整角度范围。', 'STEP 3'),
      t('Hyperbolic definitions and derivatives', '双曲定义与求导', '双曲函数由指数函数相加相减定义，恒等式和导数都可以由指数形式推导。', '双曲平方关系是余弦双曲平方减正弦双曲平方等于一。', r`\sinh x=\frac{e^x-e^{-x}}2,\quad\cosh x=\frac{e^x+e^{-x}}2,\quad\cosh^2x-\sinh^2x=1`, '先由定义推出奇偶、图像和导数；双曲正切、正割、余割与余切用相应比值或倒数表示。', r`有 \((\sinh x)'=\cosh x\)、\((\cosh x)'=\sinh x\)，且实数上 \(\cosh x\ge1\)。`, '双曲正弦与余弦求导没有普通余弦导数中的负号；双曲余割和余切在零处无定义。', 'STEP 3'),
      t('Inverse hyperbolic logarithms and substitution', '反双曲对数形式与换元', '把双曲关系改成指数的二次方程，可以推导反函数对数式，并用双曲代换消去根式。', '反双曲余弦取非负分支，真数与根式条件须同时满足。', r`\operatorname{arsinh}x=\ln(x+\sqrt{x^2+1}),\quad\operatorname{arcosh}x=\ln(x+\sqrt{x^2-1})\ (x\ge1)`, '根号含一加平方时尝试正弦双曲，含平方减一时按定义域尝试余弦双曲。', r`例如 \(x=\sinh u\) 给出 \(\sqrt{1+x^2}=\cosh u>0\)，积分可直接约去。`, '反双曲正切的实定义域是负一到一；反余弦双曲不能在小于一的实数上使用。', 'STEP 3'),
    ],
    exercises: [
      q('polar-circle-area', 'A circle in polar coordinates', r`Consider \(r=2\cos\theta\) for \(-\frac\pi2\le\theta\le\frac\pi2\). (i) Find its Cartesian equation. (ii) Use polar integration to calculate the enclosed area.`, '先乘半径再用坐标关系；面积积分中使用余弦平方降幂。', [r`Multiplying by \(r\) gives \(x^2+y^2=2x\), so \((x-1)^2+y^2=1\). The given interval has nonnegative radius and traces the circle once apart from the repeated origin endpoint.`, r`The area is \(\frac12\int_{-\frac\pi2}^{\frac\pi2}4\cos^2\theta\,d\theta=\int_{-\frac\pi2}^{\frac\pi2}(1+\cos2\theta)\,d\theta=\pi\).`], false, 'STEP 3'),
      q('inverse-hyperbolic-integral', 'A logarithm from a hyperbolic substitution', r`(i) Starting with \(x=\sinh u\), derive \(u=\ln(x+\sqrt{x^2+1})\). (ii) Hence evaluate \(\int_0^1\frac{dx}{\sqrt{1+x^2}}\).`, '令指数为正变量，解二次方程时排除负根。', [r`Let \(v=e^u>0\). Then \(2x=v-\frac1v\), so \(v^2-2xv-1=0\). Only \(v=x+\sqrt{x^2+1}\) is positive, giving the required logarithm.`, r`With \(x=\sinh u\), we have \(dx=\cosh u\,du\) and \(\sqrt{1+x^2}=\cosh u\). Thus the integral is \([u]_0^{\operatorname{arsinh}1}=\ln(1+\sqrt2)\).`], false, 'STEP 3'),
    ],
  },
  'pure/differential-equations': {
    bullets: [
      t('Separation and lost equilibrium solutions', '分离变量与被除掉的平衡解', '可分离方程把因变量和自变量放在两侧积分，但除以含未知函数的因子前要保留零解分支。', '先找平衡解，再分离变量，并用初值确定常数与适用区间。', r`y'=f(x)g(y)\quad\Longrightarrow\quad\int\frac{dy}{g(y)}=\int f(x)\,dx\quad(g(y)\ne0)`, '检查分离因子为零的解，积分后使用初值；若解出现奇点，说明所含区间。', r`例如 \(y'=y\) 的一般解为 \(Ce^x\)，其中 C 为零也包含平衡解。`, '除以未知函数会漏掉它为零的解；分离型属于共同基础，不应全部标成 STEP 3。'),
      t('Integrating factors for linear equations', '线性方程的积分因子', '标准一阶线性方程乘一个因子后，左边成为一个乘积的导数，便可整体积分。', '先把最高阶导数系数化为一，再计算积分因子。', r`y'+P(x)y=Q(x),\quad\mu=e^{\int P(x)\,dx},\quad(\mu y)'=\mu Q`, '核对线性形式，在选定区间求积分因子；最后除回并代入初值。', r`例如 \(y'+2y=1\) 乘 \(e^{2x}\)，得到 \((e^{2x}y)'=e^{2x}\)。`, '积分因子依赖标准形式中的 P；系数有奇点时，解的区间不能跨过它。', 'STEP 3'),
      t('Auxiliary equations and repeated roots', '辅助方程与重根', '常系数二阶齐次方程用指数试解转化为代数方程，不同根型对应不同的两维解空间。', '重根需要额外乘自变量，不能把同一个指数解重复写两次。', r`y''+ay'+by=0\quad\Longrightarrow\quad m^2+am+b=0`, '根据两个实根、重实根或共轭复根写出两项独立解，再用两个初值确定常数。', r`例如 \(y''-2y'+y=0\) 有重根一，通解为 \((A+Bx)e^x\)。`, '二阶方程通常需要两个独立常数；复根形式中的实部和虚部分别控制包络与振荡。', 'STEP 3'),
      t('Particular integrals and resonance', '特解与共振修正', '非齐次方程的通解是齐次通解加任一特解，试探形式与齐次解重复时需作修正。', '试探项与齐次解重合时乘足够次自变量，再代入确定系数。', r`y=y_{\mathrm{CF}}+y_{\mathrm{PI}}`, '按右端多项式、指数或三角形式选试解；代回原方程核对，而非只匹配部分系数。', r`例如 \(y''-y=e^x\) 的右端已是齐次解，可尝试 \(Ax e^x\)。`, '仅找到一个特解不是完整通解；振荡模型中的参数含义也需回到物理情境解释。', 'STEP 3'),
      t('Coupled systems and elimination', '耦合方程与消元', '两个一阶方程可通过再求导与代入，转化为单个二阶方程，再还原另一变量。', '还原后需同时满足原来两式，不能只满足导出的二阶式。', r`u'=v,\quad v'=-u\quad\Longrightarrow\quad u''+u=0`, '选择易消去的变量，再对一个方程求导；解出后由原式确定另一个变量与初值。', r`例如 \(u(0)=1,v(0)=0\) 时，上述系统给 \(u=\cos x\)、\(v=-\sin x\)。`, '并非每个非线性耦合系统都有简单显式解；陌生模型按题目所给代换或方法推进。', 'STEP 3'),
    ],
    exercises: [
      q('separable-logistic', 'Equilibria before separation', r`Consider \(y'=y(1-y)\). (i) Find its constant solutions. (ii) Solve the initial-value problem \(y(0)=\frac12\). (iii) State its limits as \(x\to\pm\infty\).`, '先找使右侧为零的常数，再用部分分式分离变量。', [r`The constant solutions are \(y=0\) and \(y=1\). For the specified solution, separation gives \(\int(\frac1y+\frac1{1-y})\,dy=x+C\), hence \(\ln\left|\frac y{1-y}\right|=x+C\).`, r`Using \(y(0)=\frac12\), obtain \(y=\frac1{1+e^{-x}}\), valid for every real \(x\). It remains strictly between zero and one, as required by the separation.`, r`The limits are zero as \(x\to-\infty\) and one as \(x\to\infty\).`]),
      q('resonant-equation', 'A resonant forcing term', r`Solve \(y''-3y'+2y=e^x\), with \(y(0)=0\) and \(y'(0)=0\). Explain why a trial particular integral \(Ce^x\) fails.`, '右端已经是齐次解，特解试成横坐标乘指数。', [r`The auxiliary equation is \((m-1)(m-2)=0\), giving \(y_{\mathrm{CF}}=Ae^x+Be^{2x}\). A trial \(Ce^x\) is annihilated by the left-hand operator, so it cannot produce the right-hand side.`, r`Try \(Kxe^x\). Substitution gives \(-Ke^x=e^x\), so \(K=-1\). Thus \(y=Ae^x+Be^{2x}-xe^x\).`, r`The initial conditions give \(A+B=0\), \(A+2B-1=0\), hence \(A=-1,B=1\). Therefore \(y=e^{2x}-(1+x)e^x\).`], false, 'STEP 3'),
    ],
  },
};
